import React, { useEffect, useMemo, useState } from 'react';
import { CheckCircle2, ClipboardList, ListFilter, Moon, Search, Sun } from 'lucide-react';
import TodoInput from './components/TodoInput';
import TodoItem from './components/TodoItem';
import TodoFilters from './components/TodoFilters';
import EmptyState from './components/EmptyState';
import type { Todo, TodoFilter, TodoPriority } from './types';

const initialTodos: Todo[] = [
  {
    id: '1',
    title: 'Plan the week ahead',
    completed: true,
    priority: 'high',
    createdAt: Date.now() - 86400000,
  },
  {
    id: '2',
    title: 'Read 20 pages of a book',
    completed: false,
    priority: 'medium',
    createdAt: Date.now() - 3600000,
  },
  {
    id: '3',
    title: 'Go for an evening walk',
    completed: false,
    priority: 'low',
    createdAt: Date.now() - 1800000,
  },
];

function App() {
  const [todos, setTodos] = useState<Todo[]>(() => {
    try {
      const saved = localStorage.getItem('focus-todos');
      return saved ? JSON.parse(saved) : initialTodos;
    } catch {
      return initialTodos;
    }
  });
  const [filter, setFilter] = useState<TodoFilter>('all');
  const [search, setSearch] = useState('');
  const [isDark, setIsDark] = useState(true);

  useEffect(() => {
    localStorage.setItem('focus-todos', JSON.stringify(todos));
  }, [todos]);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDark);
  }, [isDark]);

  const addTodo = (title: string, priority: TodoPriority) => {
    setTodos((current) => [
      {
        id: crypto.randomUUID(),
        title,
        priority,
        completed: false,
        createdAt: Date.now(),
      },
      ...current,
    ]);
  };

  const toggleTodo = (id: string) => {
    setTodos((current) => current.map((todo) => todo.id === id ? { ...todo, completed: !todo.completed } : todo));
  };

  const deleteTodo = (id: string) => {
    setTodos((current) => current.filter((todo) => todo.id !== id));
  };

  const editTodo = (id: string, title: string) => {
    setTodos((current) => current.map((todo) => todo.id === id ? { ...todo, title } : todo));
  };

  const clearCompleted = () => setTodos((current) => current.filter((todo) => !todo.completed));

  const filteredTodos = useMemo(() => todos.filter((todo) => {
    const matchesFilter = filter === 'all' || (filter === 'active' && !todo.completed) || (filter === 'completed' && todo.completed);
    return matchesFilter && todo.title.toLowerCase().includes(search.toLowerCase());
  }), [todos, filter, search]);

  const completedCount = todos.filter((todo) => todo.completed).length;
  const activeCount = todos.length - completedCount;
  const progress = todos.length ? Math.round((completedCount / todos.length) * 100) : 0;

  return (
    <div className="min-h-screen bg-slate-100 text-slate-900 transition-colors dark:bg-[#090d18] dark:text-slate-100">
      <div className="pointer-events-none fixed inset-0 overflow-hidden">
        <div className="absolute -left-24 -top-32 h-80 w-80 rounded-full bg-indigo-400/20 blur-3xl dark:bg-indigo-600/15" />
        <div className="absolute -bottom-32 -right-24 h-96 w-96 rounded-full bg-cyan-400/20 blur-3xl dark:bg-cyan-600/10" />
      </div>

      <main className="relative mx-auto min-h-screen max-w-4xl px-4 py-8 sm:px-6 sm:py-12">
        <header className="mb-10 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-indigo-500 text-white shadow-lg shadow-indigo-500/25">
              <ClipboardList size={23} />
            </div>
            <div>
              <p className="text-xl font-bold tracking-tight">Focus</p>
              <p className="text-xs text-slate-500 dark:text-slate-400">Small steps, meaningful progress</p>
            </div>
          </div>
          <button onClick={() => setIsDark(!isDark)} aria-label="Toggle theme" className="rounded-xl border border-slate-200 bg-white p-2.5 text-slate-600 transition hover:border-indigo-300 hover:text-indigo-500 dark:border-slate-800 dark:bg-slate-900/70 dark:text-slate-300 dark:hover:border-indigo-500">
            {isDark ? <Sun size={18} /> : <Moon size={18} />}
          </button>
        </header>

        <section className="mb-6 rounded-3xl border border-slate-200/80 bg-white/80 p-6 shadow-xl shadow-slate-200/40 backdrop-blur-xl dark:border-slate-800/80 dark:bg-slate-900/70 dark:shadow-black/20 sm:p-8">
          <div className="mb-7 flex flex-col justify-between gap-5 sm:flex-row sm:items-end">
            <div>
              <p className="mb-2 text-sm font-medium text-indigo-500">{activeCount ? `${activeCount} ${activeCount === 1 ? 'task' : 'tasks'} left` : 'All caught up'}</p>
              <h1 className="text-3xl font-bold tracking-tight sm:text-4xl">Your daily focus</h1>
              <p className="mt-2 text-sm text-slate-500 dark:text-slate-400">Capture what matters and make it happen.</p>
            </div>
            <div className="min-w-36 text-left sm:text-right">
              <div className="mb-2 flex items-center justify-between gap-4 text-xs font-semibold text-slate-500 sm:justify-end dark:text-slate-400">
                <span>Progress</span><span>{progress}%</span>
              </div>
              <div className="h-2 overflow-hidden rounded-full bg-slate-200 dark:bg-slate-800"><div className="h-full rounded-full bg-gradient-to-r from-indigo-500 to-cyan-400 transition-all duration-500" style={{ width: `${progress}%` }} /></div>
            </div>
          </div>
          <TodoInput onAdd={addTodo} />
        </section>

        <section className="rounded-3xl border border-slate-200/80 bg-white/80 p-4 shadow-xl shadow-slate-200/30 backdrop-blur-xl dark:border-slate-800/80 dark:bg-slate-900/70 dark:shadow-black/20 sm:p-6">
          <div className="mb-5 flex flex-col gap-4 border-b border-slate-200 pb-5 dark:border-slate-800 sm:flex-row sm:items-center sm:justify-between">
            <TodoFilters filter={filter} onFilterChange={setFilter} counts={{ all: todos.length, active: activeCount, completed: completedCount }} />
            <label className="flex items-center gap-2 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-slate-400 dark:border-slate-800 dark:bg-slate-950/50">
              <Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search tasks..." className="w-full bg-transparent text-sm text-slate-800 outline-none placeholder:text-slate-400 dark:text-white sm:w-40" />
            </label>
          </div>

          {filteredTodos.length ? <div className="space-y-3">{filteredTodos.map((todo) => <TodoItem key={todo.id} todo={todo} onToggle={toggleTodo} onDelete={deleteTodo} onEdit={editTodo} />)}</div> : <EmptyState hasTodos={todos.length > 0} />}

          {completedCount > 0 && <button onClick={clearCompleted} className="mt-6 flex items-center gap-2 text-sm font-medium text-slate-500 transition hover:text-rose-500 dark:text-slate-400"><CheckCircle2 size={16} /> Clear completed</button>}
        </section>
        <footer className="mt-7 flex items-center justify-center gap-2 text-xs text-slate-400"><ListFilter size={14} /> Built for calm, focused productivity</footer>
      </main>
    </div>
  );
}

export default App;

