import React, { useState } from 'react';
import { Plus } from 'lucide-react';
import type { TodoPriority } from '../types';

interface TodoInputProps { onAdd: (title: string, priority: TodoPriority) => void; }

function TodoInput({ onAdd }: TodoInputProps) {
  const [title, setTitle] = useState('');
  const [priority, setPriority] = useState<TodoPriority>('medium');

  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    const trimmed = title.trim();
    if (!trimmed) return;
    onAdd(trimmed, priority);
    setTitle('');
    setPriority('medium');
  };

  return <form onSubmit={submit} className="flex flex-col gap-2 sm:flex-row">
    <input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="What needs to be done?" aria-label="New task" className="min-w-0 flex-1 rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none transition placeholder:text-slate-400 focus:border-indigo-400 focus:ring-4 focus:ring-indigo-500/10 dark:border-slate-800 dark:bg-slate-950/60 dark:text-white" />
    <div className="flex gap-2">
      <select value={priority} onChange={(event) => setPriority(event.target.value as TodoPriority)} aria-label="Task priority" className="rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm outline-none dark:border-slate-800 dark:bg-slate-950/60 dark:text-slate-300">
        <option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option>
      </select>
      <button type="submit" className="flex items-center justify-center gap-2 rounded-xl bg-indigo-500 px-4 py-3 text-sm font-semibold text-white shadow-lg shadow-indigo-500/20 transition hover:bg-indigo-600 active:scale-95"><Plus size={18} /> <span className="hidden sm:inline">Add task</span></button>
    </div>
  </form>;
}

export default TodoInput;

