import React, { useState } from 'react';
import { Check, Pencil, Trash2, X } from 'lucide-react';
import type { Todo } from '../types';

interface TodoItemProps { todo: Todo; onToggle: (id: string) => void; onDelete: (id: string) => void; onEdit: (id: string, title: string) => void; }

const priorityStyles = { low: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400', medium: 'bg-amber-500/10 text-amber-600 dark:text-amber-400', high: 'bg-rose-500/10 text-rose-600 dark:text-rose-400' };

function TodoItem({ todo, onToggle, onDelete, onEdit }: TodoItemProps) {
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState(todo.title);

  const save = () => { const next = value.trim(); if (next) onEdit(todo.id, next); setEditing(false); };

  return <article className={`group flex items-center gap-3 rounded-2xl border p-3 transition-all duration-200 hover:-translate-y-0.5 hover:shadow-md ${todo.completed ? 'border-slate-200/60 bg-slate-50/70 dark:border-slate-800/60 dark:bg-slate-950/30' : 'border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900/50'}`}>
    <button onClick={() => onToggle(todo.id)} aria-label={todo.completed ? 'Mark task as active' : 'Mark task as completed'} className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2 transition ${todo.completed ? 'border-indigo-500 bg-indigo-500 text-white' : 'border-slate-300 hover:border-indigo-400 dark:border-slate-600'}`}>{todo.completed && <Check size={14} strokeWidth={3} />}</button>
    <div className="min-w-0 flex-1">
      {editing ? <input autoFocus value={value} onChange={(event) => setValue(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') save(); if (event.key === 'Escape') setEditing(false); }} className="w-full rounded-lg border border-indigo-400 bg-transparent px-2 py-1 text-sm outline-none dark:text-white" /> : <p className={`truncate text-sm font-medium ${todo.completed ? 'text-slate-400 line-through' : 'text-slate-700 dark:text-slate-200'}`}>{todo.title}</p>}
    </div>
    <span className={`hidden rounded-md px-2 py-1 text-[10px] font-bold uppercase tracking-wider sm:inline ${priorityStyles[todo.priority]}`}>{todo.priority}</span>
    <div className="flex items-center gap-1 opacity-100 transition sm:opacity-0 sm:group-hover:opacity-100">
      {editing ? <><button onClick={save} aria-label="Save task" className="rounded-lg p-2 text-emerald-500 hover:bg-emerald-500/10"><Check size={16} /></button><button onClick={() => setEditing(false)} aria-label="Cancel editing" className="rounded-lg p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800"><X size={16} /></button></> : <><button onClick={() => setEditing(true)} aria-label="Edit task" className="rounded-lg p-2 text-slate-400 hover:bg-indigo-500/10 hover:text-indigo-500"><Pencil size={16} /></button><button onClick={() => onDelete(todo.id)} aria-label="Delete task" className="rounded-lg p-2 text-slate-400 hover:bg-rose-500/10 hover:text-rose-500"><Trash2 size={16} /></button></>}
    </div>
  </article>;
}

export default TodoItem;

