import React from 'react';
import type { TodoFilter } from '../types';

interface TodoFiltersProps { filter: TodoFilter; onFilterChange: (filter: TodoFilter) => void; counts: Record<TodoFilter, number>; }

function TodoFilters({ filter, onFilterChange, counts }: TodoFiltersProps) {
  const options: { value: TodoFilter; label: string }[] = [{ value: 'all', label: 'All' }, { value: 'active', label: 'Active' }, { value: 'completed', label: 'Completed' }];
  return <nav aria-label="Task filters" className="flex w-fit items-center gap-1 rounded-xl bg-slate-100 p-1 dark:bg-slate-950/60">{options.map((option) => <button key={option.value} onClick={() => onFilterChange(option.value)} className={`rounded-lg px-3 py-1.5 text-xs font-semibold transition ${filter === option.value ? 'bg-white text-indigo-600 shadow-sm dark:bg-slate-800 dark:text-indigo-400' : 'text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200'}`}>{option.label} <span className="ml-1 opacity-60">{counts[option.value]}</span></button>)}</nav>;
}

export default TodoFilters;

